xql_query:
// ============================================================
// Rule: KCK_Multiple Public IP Logins per User
// Vendor: Keycloak
// Objective:
// Detect activity associated with KCK_Multiple Public IP Logins per User.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1110.004 - Brute Force: Credential Stuffing

config case_sensitive = false
| dataset = keycloak_keycloak_raw

// LOGIN + extração de username/grant_type
| filter type = "LOGIN"
| alter
    username   = json_extract_scalar(details_json_long_value, "$.username"),
    grant_type = json_extract_scalar(details_json_long_value, "$.grant_type")
| filter username != null and username != ""

// Apenas IP público (remove RFC1918)
| filter not (
    ip_address ~= "^10\\." or
    ip_address ~= "^192\\.168\\." or
    ip_address ~= "^172\\.(1[6-9]|2[0-9]|3[0-1])\\."
)

// Janela 1h e contagem de IPs distintos por usuário
| bin _time span = 1h
| comp
    count() as logins,
    count_distinct(ip_address) as ips_distintos,
    values(ip_address) as lista_ips
  by _time, username, client_id, realm_id, grant_type

// Threshold: >= 5 IPs públicos distintos em 1h
| filter ips_distintos >= 5
| sort desc ips_distintos
| fields _time, username, client_id, realm_id, grant_type, logins, ips_distintos, lista_ips
